      const progress=async()=>{const [rows]=await c.execute<RowDataPacket[]>('SELECT value_json FROM achievement_progress WHERE identity_key=? AND life_key=\'\' AND metric=\'ACH_D25\'',[user]);const state=typeof rows[0]?.value_json==='string'?JSON.parse(rows[0].value_json):rows[0]?.value_json;return {count:Number(state?.count??0),seen:(state?.seen??[]) as string[]};};const completed=async()=>Number((await c.execute<RowDataPacket[]>('SELECT COUNT(*) AS n FROM achievement_completions WHERE identity_key=? AND achievement_id=\'ACH_D25\'',[user]))[0][0].n);assert.equal((await progress()).count,1);assert.equal(await completed(),0);
