      const stage=async()=>Number((await c.execute<RowDataPacket[]>('SELECT realm_stage FROM characters WHERE id=?',[id]))[0][0].realm_stage);const dust=async()=>Number((await c.execute<RowDataPacket[]>('SELECT quantity FROM player_inventory WHERE character_id=? AND item_id=?',[id,dustId]))[0][0]?.quantity??0);const completion=async()=>Number((await c.execute<RowDataPacket[]>('SELECT COUNT(*) AS n FROM achievement_completions WHERE identity_key=? AND achievement_id=?',[user,'ACH_A15']))[0][0].n);
